"""Interfaz del teléfono, autocontenida y sin servicios externos."""
HTML=r'''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Desk Hub Robotec</title>
<style>
:root{color-scheme:dark;font:16px system-ui;background:#111b20;color:#f0f6f6}*{box-sizing:border-box}body{margin:0 auto;max-width:760px;padding:24px 20px 50px}header{display:flex;align-items:center;justify-content:space-between;gap:16px}h1{font-size:28px;margin:8px 0}h2{font-size:22px}h3{margin:0 0 12px}p{line-height:1.5;color:#c3d3d7}small{color:#bdd0d3}button,input{font:inherit}button{border:1px solid #5a737c;border-radius:12px;background:#253a44;color:#fff;padding:12px 16px;min-height:48px;cursor:pointer}button:disabled{opacity:.45;cursor:wait}button.primary{background:#86e2d0;color:#102923;border-color:#86e2d0}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #f3bd6a;outline-offset:3px}nav{display:flex;gap:8px;margin:24px 0;overflow:auto}nav button{flex:1;padding:12px 8px;font-size:15px;min-width:0}nav button[aria-selected=true]{background:#86e2d0;color:#102923}section[hidden]{display:none}.card{border:1px solid #405661;background:#1b2c34;padding:20px;border-radius:20px;margin:16px 0}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.row>*{flex:1}input[type=number]{width:100%;background:#111b20;color:#fff;border:1px solid #67808b;border-radius:10px;padding:12px}input[type=range]{width:100%;accent-color:#86e2d0;min-height:44px}.time{font-size:40px;letter-spacing:-1px;margin:12px 0}#song{font-size:30px;overflow-wrap:anywhere;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.photo{margin:0;padding:8px;overflow:hidden}.photo img{width:100%;aspect-ratio:16/9;object-fit:contain;background:#0b1013;border-radius:10px}.photo label{display:flex;align-items:center;gap:8px;min-height:44px;font-size:14px}.photo input{width:22px;height:22px;accent-color:#86e2d0}.photo button{width:100%;margin-top:8px}.photo small{display:block;overflow-wrap:anywhere;margin:8px}#view{width:100%;aspect-ratio:16/9;background:#081014;object-fit:contain;border-radius:18px}#message{position:sticky;top:0;z-index:1;background:#213943;border-left:4px solid #86e2d0;padding:12px 16px;min-height:48px}#session{white-space:nowrap}#cameraStatus{min-height:24px}.note{font-size:14px}a{color:#86e2d0}
</style><header><div><small>ROBOTEC · EN TU RED</small><h1>Tu Desk Hub</h1></div><small id="session">Conectando…</small></header><p id="message" role="status" aria-live="polite">Abre el QR generado en Estado → Invitados → Teléfono.</p>
<nav role="tablist" aria-label="Secciones"><button role="tab" data-tab="music" aria-selected="true">Música</button><button role="tab" data-tab="timers" aria-selected="false">Cuentas</button><button role="tab" data-tab="photos" aria-selected="false">Fotos</button><button role="tab" data-tab="camera" aria-selected="false">Cámara</button></nav>
<main><section id="music"><small>SPOTIFY CONNECT</small><div class="card"><div id="song">Tu música, aquí</div><p id="artist">Selecciona Desk Hub Robotec desde Spotify.</p><div class="row"><button data-music="prev" aria-label="Canción anterior">Anterior</button><button class="primary" id="play" data-music="play">Reproducir</button><button data-music="next">Siguiente</button></div><label for="volume"><p>Volumen <span id="volumeText"></span></p></label><input id="volume" type="range" min="0" max="100" step="5" value="50"></div></section>
<section id="timers" hidden><h2>Cuentas independientes</h2><p>Continúan aunque cierres esta página.</p><div id="timerCards"></div></section>
<section id="photos" hidden><div class="row"><h2>Tus fotos</h2><button id="reloadPhotos">Actualizar</button></div><p>Descarga el archivo original guardado en la Pi.</p><button id="downloadSelection">Descargar selección (0)</button><div class="grid" id="photoGrid"></div><div class="row"><button id="photoPrev">Anterior</button><small id="photoPage"></small><button id="photoNext">Siguiente</button></div><h2>Timelapses en vídeo</h2><p>Exporta una sesión en la pantalla del Hub para descargar su MP4 aquí.</p><div id="videoList"></div></section>
<section id="camera" hidden><h2>Encuadre en directo</h2><img id="view" alt="El encuadre aparecerá al activar la cámara"><p id="cameraStatus">La cámara está detenida.</p><div class="row"><button id="cameraStart" class="primary">Activar cámara</button><button id="cameraStop">Pausar vista</button><button id="capture">Tomar foto</button></div><p class="note">La vista no guarda imágenes. Tomar foto crea un archivo en la galería. El Hub muestra cuándo está activa la cámara.</p></section></main><p class="note">Acceso temporal para el anfitrión. Al bloquear el Hub o vencer el enlace tendrás que escanear otro QR. Las consultas automáticas no impiden el bloqueo por inactividad.</p><button id="close">Cerrar enlace</button>
<script>
const $=id=>document.getElementById(id);let token='',tab='music',live=false,frameBusy=false,frameUrl='',photos=[],page=0,photoUrls=[],photoEpoch=0,pollBusy=false,selectedPhotos=new Set();
const tell=s=>$('message').textContent=s;
function expire(){token='';live=false;$('session').textContent='Enlace cerrado';$('view').removeAttribute('src');if(frameUrl)URL.revokeObjectURL(frameUrl);clearPhotos();$('videoList').replaceChildren();tell('Enlace cerrado. Genera otro QR en el Hub.');}
async function api(path,data,blob=false){if(!token&&path!=='pair')throw Error('Escanea un nuevo QR desde el Hub.');const response=await fetch('/api/'+path,{method:data?'POST':'GET',headers:{...(token?{Authorization:'Bearer '+token}:{}),...(data?{'Content-Type':'application/json'}:{})},body:data?JSON.stringify(data):undefined,cache:'no-store',signal:AbortSignal.timeout(blob?120000:7000)});if(response.status===401){expire();throw Error('El QR o la sesión ya no son válidos.');}if(!response.ok){const error=await response.json();throw Error(error.error||'No se pudo completar la acción.');}return blob?response.blob():response.json();}
async function command(data,button){if(button)button.disabled=true;try{const result=await api('command',data);tell(result.message);return true;}catch(error){tell(error.message);return false;}finally{if(button)button.disabled=false;}}
function button(label,run){const b=document.createElement('button');b.textContent=label;b.onclick=()=>run(b);return b;}
for(let i=0;i<3;i++){const card=document.createElement('div');card.className='card';const title=document.createElement('h3');title.id='timerName'+i;const time=document.createElement('div');time.id='timerTime'+i;time.className='time';const input=document.createElement('input');input.type='number';input.min=1;input.max=1440;input.value=[25,5,60][i];input.id='minutes'+i;input.setAttribute('aria-label','Duración en minutos');const set=button('Ajustar minutos',b=>command({command:'timer',operation:'set',index:i,minutes:Number(input.value)},b));const row=document.createElement('div');row.className='row';row.append(input,set);const controls=document.createElement('div');controls.className='row';controls.style.marginTop='12px';for(const [label,operation] of [['Iniciar','start'],['Pausar','pause'],['Reiniciar','reset']])controls.append(button(label,b=>command({command:'timer',operation,index:i},b)));card.append(title,time,row,controls);$('timerCards').append(card);}
document.querySelectorAll('[data-music]').forEach(b=>b.onclick=()=>command({command:'music',operation:b.dataset.music},b));$('volume').oninput=()=>{$('volumeText').textContent=$('volume').value+' %';};$('volume').onchange=()=>command({command:'music',operation:'volume',value:Number($('volume').value)});
async function state(){if(!token||pollBusy||document.hidden)return;pollBusy=true;try{const s=await api('state');$('session').textContent=Math.ceil(s.session/60)+' min';$('song').textContent=s.music.title||'Tu música, aquí';$('artist').textContent=s.music.artist||'Selecciona Desk Hub Robotec desde Spotify.';const playing=s.music.status==='playing'&&s.music.is_active;$('play').textContent=playing?'Pausar':'Reproducir';$('play').dataset.music=playing?'pause':'play';if(document.activeElement!==$('volume')){$('volume').value=s.music.volume||0;$('volumeText').textContent=(s.music.volume||0)+' %';}s.timers.forEach((t,i)=>{$('timerName'+i).textContent=t.name+ (t.running?' · En marcha':'');$('timerTime'+i).textContent=String(Math.floor(t.seconds/60)).padStart(2,'0')+':'+String(t.seconds%60).padStart(2,'0');});$('cameraStatus').textContent=s.camera;}catch(e){tell(e.message);}finally{pollBusy=false;}}
function clearPhotos(){photoEpoch++;selectedPhotos.clear();$('downloadSelection').textContent='Descargar selección (0)';photoUrls.forEach(u=>URL.revokeObjectURL(u));photoUrls=[];$('photoGrid').replaceChildren();}
async function renderPhotos(){clearPhotos();const epoch=photoEpoch;$('photoPage').textContent=(page+1)+' / '+Math.max(1,Math.ceil(photos.length/6));$('photoPrev').disabled=page===0;$('photoNext').disabled=(page+1)*6>=photos.length;for(const name of photos.slice(page*6,page*6+6)){if(epoch!==photoEpoch)return;const card=document.createElement('div');card.className='card photo';const img=document.createElement('img');img.alt='Foto guardada';const caption=document.createElement('small');caption.textContent=name;const choice=document.createElement('input');choice.type='checkbox';choice.setAttribute('aria-label','Seleccionar '+name);choice.onchange=()=>{if(choice.checked)selectedPhotos.add(name);else selectedPhotos.delete(name);$('downloadSelection').textContent='Descargar selección ('+selectedPhotos.size+')';};const choiceLabel=document.createElement('label');choiceLabel.append(choice,document.createTextNode('Seleccionar'));card.append(choiceLabel,img,caption,button('Descargar',async b=>{b.disabled=true;try{const blob=await api('photo?name='+encodeURIComponent(name),null,true);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);tell('Descarga preparada.');}catch(e){tell(e.message);}finally{b.disabled=false;}}));$('photoGrid').append(card);try{const blob=await api('thumb?name='+encodeURIComponent(name),null,true);if(epoch!==photoEpoch)return;const url=URL.createObjectURL(blob);photoUrls.push(url);img.src=url;}catch(e){tell(e.message);}}if(!photos.length)tell('Todavía no hay fotos en el álbum.');}
async function loadPhotos(){try{photos=(await api('photos')).photos;page=0;await renderPhotos();await loadVideos();}catch(e){tell(e.message);}}
async function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
$('downloadSelection').onclick=async()=>{if(!selectedPhotos.size){tell('Selecciona hasta seis fotos de esta página.');return;}$('downloadSelection').disabled=true;tell('Preparando las fotos originales…');try{const blob=await api('archive',{names:[...selectedPhotos]},true);await downloadBlob(blob,'fotos-robotec.zip');tell('ZIP preparado con los originales.');}catch(e){tell(e.message);}finally{$('downloadSelection').disabled=false;}};
async function loadVideos(){try{const list=(await api('videos')).videos;$('videoList').replaceChildren();for(const video of list){const card=document.createElement('div');card.className='card';const title=document.createElement('p');title.textContent=new Date(video.created*1000).toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'})+' · '+(video.frames/video.fps).toFixed(1)+' s · '+(video.bytes/1048576).toFixed(1)+' MiB';card.append(title,button('Descargar MP4',async b=>{b.disabled=true;tell('Preparando el vídeo…');try{await downloadBlob(await api('video?name='+encodeURIComponent(video.name),null,true),video.name);tell('Vídeo preparado para descargar.');}catch(e){tell(e.message);}finally{b.disabled=false;}}));$('videoList').append(card);}}catch(e){tell(e.message);}}
$('reloadPhotos').onclick=loadPhotos;$('photoPrev').onclick=()=>{page=Math.max(0,page-1);renderPhotos();};$('photoNext').onclick=()=>{page=Math.min(Math.ceil(photos.length/6)-1,page+1);renderPhotos();};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{const next=b.dataset.tab;if(tab==='camera'&&next!=='camera'&&live){live=false;command({command:'camera',operation:'stop'});}tab=next;document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==tab);document.querySelectorAll('[data-tab]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));if(tab==='photos')loadPhotos();});
$('cameraStart').onclick=async()=>{live=await command({command:'camera',operation:'start'},$('cameraStart'));};$('cameraStop').onclick=()=>{live=false;command({command:'camera',operation:'stop'},$('cameraStop'));};$('capture').onclick=()=>{live=false;command({command:'camera',operation:'capture'},$('capture'));};
async function frame(){if(!token||!live||tab!=='camera'||frameBusy||document.hidden)return;frameBusy=true;try{const blob=await api('frame',null,true);if(!live||!token)return;const url=URL.createObjectURL(blob);$('view').src=url;if(frameUrl)URL.revokeObjectURL(frameUrl);frameUrl=url;}catch(e){$('cameraStatus').textContent=e.message;}finally{frameBusy=false;}}
$('close').onclick=async()=>{await command({command:'close'});expire();};document.addEventListener('visibilitychange',()=>{if(document.hidden&&live){live=false;command({command:'camera',operation:'stop'});}});
(async()=>{const pair=new URLSearchParams(location.hash.slice(1)).get('pair');history.replaceState(null,'',location.pathname);if(!pair)return;try{const result=await api('pair',{pair});token=result.session;tell('Enlazado. Tú eliges qué abrir o controlar.');state();}catch(e){tell(e.message);}})();setInterval(state,1000);setInterval(frame,250);
</script></html>'''
